package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.model.BrandResponseimport com.dy.artisan3d.domain.model.Brandimport com.dy.artisan3d.domain.repository.BrandRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.Constants.FILE_URLimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getclass BrandRepositoryImpl(    private val httpClient: HttpClient) : BrandRepository {    override suspend fun getBrands(lang: String): List<Brand> {        return try {            val response: BrandResponse = httpClient.get("${BASE_URL}brands").body()            response.data                .filter { dto -> dto.products_count > 0 }                .map { dto ->                val translation = dto.translations[lang] ?: dto.translations["en"]                Brand(                    id = dto.id,                    image = dto.image?.let { FILE_URL + it },                    productsCount = dto.products_count,                    name = translation?.name ?: "Unknown",                    address = translation?.address ?: ""                )            }        } catch (e: Exception) {            emptyList()        }    }}